package com.autoops.execution.controller;import com.autoops.execution.entity.*;import com.autoops.execution.service.ExecutionControlService;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/executions")public class ExecutionControlController{private final ExecutionControlService service;public ExecutionControlController(ExecutionControlService s){service=s;}@PostMapping("/{id}/stop")public Execution stop(@PathVariable Long id){return service.stop(id);}@PostMapping("/steps/{id}/retry")public StepRun retry(@PathVariable Long id){return service.retry(id);}}
